import {useLayoutEffect} from 'react';
import {useFrame,useThree} from '@react-three/fiber';
import {Box3,Mesh,OrthographicCamera,Vector3} from 'three';
import type {AssetEntity} from '../../../src/operations/scene/assets/registry';
import type {FamilySample} from './poses';
import {actualMeshStats,contactSurfaces,rigidClearance} from './surface';

export function Diagnostics({entity,sample,angle,revision,manifestHash}:{readonly entity:AssetEntity;readonly sample:FamilySample;readonly angle:string;readonly revision:number;readonly manifestHash:string}){
  const {camera,gl,scene,invalidate}=useThree();
  useLayoutEffect(()=>{entity.root.updateMatrixWorld(true);const box=new Box3().setFromObject(entity.root),target=box.getCenter(new Vector3()),size=box.getSize(new Vector3()),owner=sample.ownerPose;target.y=2;const offset=angle==='side'?[0,9,20]:angle==='rear'?[-15,11,-16]:[14,11,16];camera.position.copy(target).add(new Vector3(...offset));camera.lookAt(target);if(camera instanceof OrthographicCamera)camera.zoom=angle==='close'?120:Math.min(75,750/Math.max(8,size.x,size.z));camera.updateProjectionMatrix();camera.updateMatrixWorld(true);gl.domElement.dataset.cameraState=JSON.stringify({angle,matrixWorld:camera.matrixWorld.toArray(),ownerPose:owner});invalidate();},[entity,sample,angle,revision,camera,gl,invalidate]);
  useFrame(()=>{if(entity.level===null)return;scene.updateMatrixWorld(true);const nodes:Readonly<Record<string,unknown>>[]=[];let triangles=0;entity.root.traverse(n=>{if(n instanceof Mesh)triangles+=(n.geometry.index?.count??n.geometry.getAttribute('position').count)/3;if(typeof n.userData.semantic_id==='string')nodes.push({id:n.userData.semantic_id,matrixWorld:n.matrixWorld.toArray(),visible:n.visible,operationalState:n.userData.operationalState??null});});const material:Mesh[]=[];scene.traverse(n=>{if(n instanceof Mesh&&n.userData.poseMaterial===true)material.push(n);});const body=material[0];if(!body)return;const contact=new Vector3(...sample.pose.contact_m),socket=entity.asset.sockets.find(s=>s.id===sample.envelope.anchor.socket_id),part=socket&&entity.nodes.get(socket.node_id);if(!socket||!part)throw new RangeError('Actual contact frame absent');const normal=new Vector3(...socket.normal).applyQuaternion(part.getWorldQuaternion(part.quaternion.clone()));const machine=contactSurfaces(entity.root,contact,normal),stock=contactSurfaces(body,contact,normal.clone().negate()),stats=actualMeshStats(body),clearance=rigidClearance(entity.root,body);gl.domElement.dataset.assetState=JSON.stringify({assetId:entity.asset.id,variant:entity.asset.variant,lod:entity.level,phase:sample.frame.name,manifestSha256:manifestHash,authority:'t58-fixed-contract',businessKey:entity.key,rootUuid:entity.root.uuid,ownerPose:sample.ownerPose,triangles,nodes,pose:sample.pose,envelope:sample.envelope,snapshot:sample.snapshot,materialCount:material.length,material:{...stats,proof:body.userData.proof,uuid:body.uuid,businessMaterialId:body.userData.materialId,versionId:body.userData.versionId,attachmentId:body.userData.attachmentId},machineContact:machine,materialContact:stock,rigidClearance:clearance});gl.domElement.dataset.ready='true';});
  return null;
}
